    uspan[i] = (nuint)(i * 100);

Console.WriteLine();
Console.WriteLine($"nuint size: {sizeof(nuint)} bytes");
for (int i = 0; i < uspan.Length; i++)
    Console.WriteLine($"uspan[{i}] = {uspan[i]}");

